from datetime import datetime, timedelta

def next_run(cron_expr: str) -> datetime:
    def parse(field, lo, hi):
        values = set()
        for part in field.split(','):
            step = 1
            if '/' in part:
                part, s = part.split('/')
                step = int(s)
            if part == '*':
                start, end = lo, hi
            elif '-' in part:
                start, end = map(int, part.split('-'))
            else:
                start = end = int(part)
            values.update(range(start, end + 1, step))
        return values

    mi, h, dom, mo, _ = cron_expr.split()
    minutes, hours = parse(mi, 0, 59), parse(h, 0, 23)
    days, months = parse(dom, 1, 31), parse(mo, 1, 12)

    t = datetime.now().replace(second=0, microsecond=0) + timedelta(minutes=1)
    while True:
        if t.month not in months:
            t = (t.replace(day=1, hour=0, minute=0) + timedelta(days=32)).replace(day=1)
        elif t.day not in days:
            t = (t + timedelta(days=1)).replace(hour=0, minute=0)
        elif t.hour not in hours:
            t = (t + timedelta(hours=1)).replace(minute=0)
        elif t.minute not in minutes:
            t += timedelta(minutes=1)
        else:
            return t

# Test: 7 oktober kl 02:00 varje år
print(next_run('0 2 7 10 *'))  # t.ex. 2027-10-07 02:00:00
