import re

def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    ip_pattern = re.compile(r"\b(?:\d{1,3}\.){3}\d{1,3}\b")
    unauthorized = set()
    with open(log_path, "r") as f:
        for line in f:
            match = ip_pattern.search(line)
            if match and match.group() not in allowed_ips:
                unauthorized.add(match.group())
    return sorted(unauthorized)
```

