from datetime import datetime
import psutil

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    log, seen = [], set()
    try:
        while True:
            for c in psutil.net_connections(kind="tcp"):
                if c.status == "ESTABLISHED" and c.laddr and c.laddr.ip == host and c.raddr:
                    key = (c.raddr.ip, c.raddr.port)
                    if key not in seen:
                        seen.add(key)
                        log.append({
                            "timestamp": datetime.now().isoformat(),
                            "source": f"{c.raddr.ip}:{c.raddr.port}",
                        })
            time.sleep(interval_s)
    except KeyboardInterrupt:
        return log
