def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """Identifierar misstänkta intrångsförsök baserat på upprepade
    misslyckade anslutningar eller portskanning från samma IP."""
    attempts = {}
    for p in packet_log:
        ip = p.get("src_ip")
        if not ip:
            continue
        entry = attempts.setdefault(ip, {"fails": 0, "ports": set()})
        if p.get("status") == "failed":
            entry["fails"] += 1
        if "port" in p:
            entry["ports"].add(p["port"])

    return [
        {"src_ip": ip, "failed_attempts": e["fails"], "ports_scanned": len(e["ports"])}
        for ip, e in attempts.items()
        if e["fails"] >= 5 or len(e["ports"]) >= 10
    ]
