import os
import stat


def audit_file_permissions(directory: str) -> list[dict]:
    findings = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                mode = stat.S_IMODE(os.lstat(path).st_mode)
            except OSError:
                continue
            issues = []
            if mode & stat.S_IWOTH:
                issues.append("world-writable")
            if mode & stat.S_IROTH and mode & stat.S_IXOTH:
                issues.append("world-readable-executable")
            if mode & 0o6000:
                issues.append("setuid/setgid")
            if issues:
                findings.append({
                    "path": path,
                    "mode": oct(mode),
                    "issues": issues,
                })
    return findings
