    """Hittar skrivbara filer som kan utnyttjas för privilege escalation."""
    writable = []
    for root, _, files in os.walk(directory):
        for name in files:
            path = os.path.join(root, name)
            try:
                st = os.lstat(path)
                if stat.S_ISREG(st.st_mode) and (
                    st.st_mode & stat.S_IWOTH or os.access(path, os.W_OK)
                ):
                    writable.append(path)
            except OSError:
                continue
    return writable
