import math
from collections import Counter
from scapy.all import rdpcap, DNS, DNSQR

def analyze_dns_traffic(pcap_file: str) -> dict:
    def entropy(s: str) -> float:
        c = Counter(s)
        return -sum((n / len(s)) * math.log2(n / len(s)) for n in c.values()) if s else 0

    queries = []
    for pkt in rdpcap(pcap_file):
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR) and pkt[DNS].qr == 0:
            queries.append(pkt[DNSQR].qname.decode(errors="ignore").rstrip("."))

    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    domain_counts = Counter(".".join(q.split(".")[-2:]) for q in queries)

    for q in set(queries):
        labels = q.split(".")
        name = labels[0]
        ent = entropy(name)
        # DGA: hög entropi + långt namn utan vokaler-mönster
        if len(name) > 12 and ent > 3.5 and sum(c in "aeiou" for c in name) / len(name) < 0.3:
            suspicious["dga"].append(q)
        # Tunneling: mycket långa labels eller TXT-liknande payloads
        if any(len(l) > 40 for l in labels) or len(q) > 100:
            suspicious["tunneling"].append(q)
        # Exfiltration: många unika subdomäner under samma basdomän
        base = ".".join(labels[-2:])
        if domain_counts[base] > 50 and len(labels) > 2:
            suspicious["exfiltration"].append(q)

    return {
        "total_queries": len(queries),
        "unique_domains": len(set(queries)),
        "suspicious": {k: sorted(v) for k, v in suspicious.items()},
    }
